void BaseWindow::SetBounds(const gfx::Rect& bounds,
                           gin::Arguments* const args) {
  bool animate = false;
  args->GetNext(&animate);
  window_->SetBounds(bounds, animate);
}

void NativeWindowViews::SetBounds(const gfx::Rect& bounds, bool animate) {
#if BUILDFLAG(IS_WIN)
  if (is_moving_ || is_resizing_) {
    pending_bounds_change_ = bounds;
  }
#endif

#if BUILDFLAG(IS_WIN) || BUILDFLAG(IS_LINUX)
  // On Linux and Windows the minimum and maximum size should be updated with
  // window size when window is not resizable.
  if (!CanResize()) {
    SetMaximumSize(bounds.size());
    SetMinimumSize(bounds.size());
  }
#endif

  widget()->SetBounds(LogicalToWidgetBounds(bounds));
}

bool NativeWindowViews::CanResize() const {
#if BUILDFLAG(IS_WIN)
  return has_frame() ? resizable_ && thick_frame_ : resizable_;
#else
  return resizable_;
#endif
}

// On Windows we rely on the CanResize() to indicate whether window can be
  // resized, and it should be set before window is created.
  options.Get(options::kResizable, &resizable_);
  options.Get(options::kMinimizable, &minimizable_);
  options.Get(options::kMaximizable, &maximizable_);

  // Transparent window must not have thick frame.
  options.Get("thickFrame", &thick_frame_);
  if (transparent())
    thick_frame_ = false;

// The given window is most likely not rectangular since it is translucent and
  // has no standard frame, don't show a shadow for it.
  if (IsTranslucent() && !has_frame())
    params.shadow_type = InitParams::ShadowType::kNone;

void NotifyIcon::PopUpContextMenu(const gfx::Point& pos,
                                  base::WeakPtr<ElectronMenuModel> menu_model) {
  // Returns if context menu isn't set.
  if (menu_model == nullptr && menu_model_ == nullptr)
    return;

  // Set our window as the foreground window, so the context menu closes when
  // we click away from it.
  if (!SetForegroundWindow(window_))
    return;

  // Cancel current menu if there is one.
  CloseContextMenu();

  // Show menu at mouse's position by default.
  gfx::Rect rect(pos, gfx::Size());
  if (pos.IsOrigin())
    rect.set_origin(display::Screen::Get()->GetCursorScreenPoint());

  if (menu_model) {
    menu_runner_ = std::make_unique<views::MenuRunner>(
        menu_model.get(), views::MenuRunner::HAS_MNEMONICS);
  } else {
    menu_runner_ = std::make_unique<views::MenuRunner>(
        menu_model_, views::MenuRunner::HAS_MNEMONICS);
  }
  menu_runner_->RunMenuAt(nullptr, nullptr, rect,
                          views::MenuAnchorPosition::kTopLeft,
                          ui::mojom::MenuSourceType::kMouse);
}
